// AMB-1 Evolved installer UI. GPL-3.0-only; protocol implementation credited in fm1ota.js.
import {Updater} from './fm1ota.js';
import {productOf,logicalImage} from './fm1pkg.js';
const $=id=>document.getElementById(id);
const STOCK_SHA='db1642b2b6fa5c2cccb11ffd13878068bb28601678d3644049f99dc40e7edb8a';
let manifest,packs={},access,busy=false,connected=false,target='wolf',logLines=[];
let pending;try{pending=JSON.parse(localStorage.getItem('evolved-pending')||'null');if(['wolf','amb','stock'].includes(pending?.target))target=pending.target;}catch{}
document.querySelectorAll('[name=target]').forEach(e=>e.checked=e.value===target);
function log(s){logLines.push(new Date().toISOString()+' '+s);if(logLines.length>500)logLines.shift();$('log').textContent=logLines.join('\n');}
function refresh(){const valid=!!packs[target];$('install').disabled=busy||!connected||!valid||!$('ready').checked;$('connect').disabled=busy;$('stockFile').disabled=busy;$('ready').disabled=busy;document.querySelectorAll('[name=target]').forEach(e=>e.disabled=busy);$('stockBox').hidden=target!=='stock';$('packageStatus').textContent=valid?'SHA-256 geprüft · '+packs[target].product+' · '+packs[target].raw.length+' Bytes':'Zielpaket noch nicht verfügbar.';}
async function sha(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
export async function checkedPackage(raw,hash,product){if(raw.length<960||raw.length>2*1024*1024)throw Error('Unzulässige Paketgrösse.');if(await sha(raw)!==hash)throw Error('Paket-Prüfsumme stimmt nicht. Es wird nichts geschrieben.');const id=productOf(raw);if(!/^FM-1_\d+$/.test(id)||product&&id!==product)throw Error('Falsche Paketkennung.');return {raw,product:id,image:logicalImage(raw),hash};}
async function midi(){if(!navigator.requestMIDIAccess)throw Error('Bitte diese HTTPS-Seite in Chrome auf deinem Mac öffnen.');if(!access)access=await navigator.requestMIDIAccess({sysex:true});return access;}
async function exclusive(fn){if(!navigator.locks)throw Error('Dieser Browser unterstützt die Installationssperre nicht. Bitte aktuelles Chrome verwenden.');return navigator.locks.request('amb1-evolved-fm1-update',{ifAvailable:true},async lock=>{if(!lock)throw Error('Ein anderer Installer-Tab dieser Seite ist aktiv.');return fn();});}
function oneDevice(a){const inputs=[...a.inputs.values()].filter(p=>p.state!=='disconnected'&&/fm-1|felucca|ota|composite|sinco|usb-midi/i.test(p.name||''));if(inputs.length!==1)throw Error('Bitte genau einen FM-1 anschliessen. Gefundene mögliche Eingänge: '+inputs.length);}
async function identify(){const a=await midi();oneDevice(a);const up=new Updater(a,log);const d=await up.find(id=>/^(ota-)?FM-1$/i.test(id.model));if(!d)throw Error('Keine passende Geräteantwort. Andere MIDI-Apps schliessen und Verbindung prüfen.');const text=d.id.text;d.link.close();return text;}
$('connect').onclick=async()=>{if(busy)return;busy=true;refresh();try{await exclusive(async()=>{const id=await identify();connected=true;$('device').textContent='Erkannt: '+id;log('Identität: '+id+' (nur Abfrage, kein Flashen)');});}catch(e){connected=false;$('device').textContent=e.message;log(e.message);}finally{busy=false;refresh();}};
$('ready').onchange=refresh;document.querySelectorAll('[name=target]').forEach(e=>e.onchange=()=>{target=e.value;$('ready').checked=false;refresh();});
$('stockFile').onchange=async e=>{delete packs.stock;refresh();try{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('Datei zu gross.');packs.stock=await checkedPackage(new Uint8Array(await f.arrayBuffer()),STOCK_SHA);$('stockStatus').textContent='Original V15 geprüft: '+packs.stock.product;}catch(e){$('stockStatus').textContent=e.message;}refresh();};
const messages={start:'Gerät bestätigt; Paket wird angefordert.',verify:'Phase 1/2: Update-Loader vorbereiten.',loader:'Warte auf den Update-Loader …',write:'Phase 2/2: Firmware schreiben. Strom und USB angeschlossen lassen.',reboot:'Schreiben beendet; Neustart und Firmware-Kennung prüfen …',done:'Installation und Gerätekennung bestätigt.'};
function step(k,n){$('status').textContent=messages[k]||k;if(k==='verify')$('progress').value=Math.min(10,n/74*10);if(k==='write')$('progress').value=10+Math.min(84,n/1167*84);if(k==='reboot')$('progress').value=95;if(k==='done')$('progress').value=100;if(!['verify','write'].includes(k)||n%100===0)log(k+' '+(n??''));}
const errors={notfound:'FM-1 nicht gefunden.',model:'Gerätemodell passt nicht.',lost:'USB-Verbindung unterbrochen. Gerät eingeschaltet lassen und den Wiederherstellungsweg lesen.',stopped:'Übertragung gestoppt. Kein Erfolg bestätigt.',noloader:'Update-Loader nicht erreichbar. Kein Erfolg bestätigt.',noreturn:'Neustart nicht bestätigt. Protokoll sichern.',mismatch:'Gerät meldet eine andere Firmware-Kennung. Kein Erfolg bestätigt.',badreq:'Ungültige Datenanforderung; Übertragung angehalten.'};
$('install').onclick=async()=>{if(busy||!connected||!packs[target]||!$('ready').checked)return;const selected=target,pkg=packs[selected];busy=true;refresh();let wake;try{await exclusive(async()=>{const a=await midi();oneDevice(a);await checkedPackage(pkg.raw,pkg.hash,pkg.product);try{wake=await navigator.wakeLock?.request('screen');}catch{}try{localStorage.setItem('evolved-pending',JSON.stringify({target:selected,hash:pkg.hash}));}catch{}log('START '+selected+' '+pkg.product+' SHA256 '+pkg.hash);$('progress').value=0;const up=new Updater(a,log);const loader=await up.find(id=>/^ota-FM-1$/i.test(id.model));if(loader){loader.link.close();log('Loader aktiv: Schreibphase erneut starten.');if(!await up.resume(pkg.image,step))throw Error('Loader-Schreiben nicht abgeschlossen.');step('reboot');const back=await up.waitFor(id=>!/^ota-/i.test(id.model),40000);if(!back)throw Error('Keine Gerätekennung nach Wiederherstellung.');const id=back.id.text;back.link.close();if(id!==pkg.product)throw Error('Abweichende Kennung nach Wiederherstellung: '+id);step('done',id);}else await up.install(pkg.image,pkg.product,step);$('device').textContent='Bestätigt: '+pkg.product;try{localStorage.removeItem('evolved-pending');}catch{}pending=null;log('ENDE: Kennung bestätigt. Audio/Bedienung noch am Gerät testen.');});}catch(e){$('status').textContent=selected==='stock'&&e.code==='mismatch'?'Herstellerpaket übertragen; Gerät meldet '+e.detail+'. Original-Startbildschirm prüfen: Kennung weicht vom Paket ab, Wiederherstellung nicht automatisch bestätigt.':(errors[e.code]||e.message)+(e.detail?' '+e.detail:'');log('FEHLER '+(e.code||'')+' '+e.message);connected=false;}finally{try{await wake?.release();}catch{}busy=false;$('ready').checked=false;refresh();}};
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([logLines.join('\n')],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='AMB1-Evolved-Installationsprotokoll.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
(async()=>{try{const res=await fetch('manifest.json',{cache:'no-store'});if(!res.ok)throw Error('Paketliste nicht verfügbar.');manifest=await res.json();if(pending)log('Vorheriger Vorgang nicht bestätigt: '+pending.target+'. Ziel wieder ausgewählt.');for(const name of ['amb','wolf']){const m=manifest[name],r=await fetch(m.file,{cache:'no-store'});if(!r.ok)throw Error(name+': Download fehlgeschlagen.');packs[name]=await checkedPackage(new Uint8Array(await r.arrayBuffer()),m.sha256,m.product);log(name+' lokal geprüft: '+m.product);}}catch(e){$('status').textContent=e.message;log(e.message);}refresh();})();
